resolved as (
    select
        HUB_RISK_OBJECT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CUMULATIVE_BONUS_APPLICABLE_INDICATOR end) as CUMULATIVE_BONUS_APPLICABLE_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATIONSHIP_TO_PROPOSER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RELATIONSHIP_TO_PROPOSER end)) as RELATIONSHIP_TO_PROPOSER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then HEIGHT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then HEIGHT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then HEIGHT end)) as HEIGHT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then WEIGHT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then WEIGHT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then WEIGHT end)) as WEIGHT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRE_EXISTING_DISEASE_DESCRIPTION end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_EXISTING_DISEASE_DESCRIPTION end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PRE_EXISTING_DISEASE_DESCRIPTION end)) as PRE_EXISTING_DISEASE_DESCRIPTION,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then BODY_MASS_INDEX end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BODY_MASS_INDEX end)) as BODY_MASS_INDEX,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then SMOKER_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SMOKER_INDICATOR end)) as SMOKER_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_CARD_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then HEALTH_CARD_NUMBER end)) as HEALTH_CARD_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_RISK_LOADING_PERCENTAGE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_RISK_LOADING_PERCENTAGE end)) as MEMBER_RISK_LOADING_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OCCUPATION_RISK_CLASS end) as OCCUPATION_RISK_CLASS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_TYPE end) as MEMBER_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PRE_EXISTING_DISEASE_INDICATOR end) as PRE_EXISTING_DISEASE_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when CUMULATIVE_BONUS_APPLICABLE_INDICATOR is not null or RELATIONSHIP_TO_PROPOSER is not null or HEIGHT is not null or WEIGHT is not null or PRE_EXISTING_DISEASE_DESCRIPTION is not null or BODY_MASS_INDEX is not null or SMOKER_INDICATOR is not null or HEALTH_CARD_NUMBER is not null or MEMBER_RISK_LOADING_PERCENTAGE is not null or OCCUPATION_RISK_CLASS is not null or MEMBER_TYPE is not null or PRE_EXISTING_DISEASE_INDICATOR is not null
                     then md5(upper(coalesce(cast(CUMULATIVE_BONUS_APPLICABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(RELATIONSHIP_TO_PROPOSER as varchar), '') || '|' || coalesce(cast(HEIGHT as varchar), '') || '|' || coalesce(cast(WEIGHT as varchar), '') || '|' || coalesce(cast(PRE_EXISTING_DISEASE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(BODY_MASS_INDEX as varchar), '') || '|' || coalesce(cast(SMOKER_INDICATOR as varchar), '') || '|' || coalesce(cast(HEALTH_CARD_NUMBER as varchar), '') || '|' || coalesce(cast(MEMBER_RISK_LOADING_PERCENTAGE as varchar), '') || '|' || coalesce(cast(OCCUPATION_RISK_CLASS as varchar), '') || '|' || coalesce(cast(MEMBER_TYPE as varchar), '') || '|' || coalesce(cast(PRE_EXISTING_DISEASE_INDICATOR as varchar), '')))
                end as SAT_RISK_PERSON_INSURED_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_PERSON_INSURED_HASHDIFF is not null
